{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { mkdir, readFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { DatabaseSync } from 'node:sqlite';

const directory = dirname(fileURLToPath(import.meta.url));
const databasePath = resolve(process.env.DB_PATH || join(directory, 'data', 'workboard.sqlite'));
await mkdir(dirname(databasePath), { recursive: true });
const database = new DatabaseSync(databasePath);
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)),
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
  )
`);
database.exec('PRAGMA foreign_keys = ON');

const projectColumns = database.prepare('PRAGMA table_info(projects)').all();
if (!projectColumns.some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}

const listProjects = database.prepare(`
  SELECT p.id, p.name, p.archived,
    COUNT(t.id) AS totalCount,
    COALESCE(SUM(t.completed), 0) AS completedCount
  FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
  WHERE p.archived = ?
  GROUP BY p.id ORDER BY p.id
`);
const findProject = database.prepare('SELECT id, name, archived FROM projects WHERE id = ?');
const createProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
const renameProject = database.prepare('UPDATE projects SET name = ? WHERE id = ?');
const updateProjectArchived = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const listTasks = database.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const findTask = database.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE id = ? AND project_id = ?');
const createTask = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const updateTaskCompletion = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');
const html = await readFile(join(directory, 'index.html'));

async function readJson(request) {
  let body = '';
  for await (const chunk of request) body += chunk;
  try {
    return JSON.parse(body);
  } catch {
    return null;
  }
}

function sendJson(response, status, value) {
  response.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(value));
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, 'http://localhost');
  if (request.method === 'GET' && url.pathname === '/health') {
    sendJson(response, 200, { status: 'ok' });
    return;
  }
  if (request.method === 'GET' && url.pathname === '/api/projects') {
    const filter = url.searchParams.get('filter') === 'Archived' ? 1 : 0;
    sendJson(response, 200, listProjects.all(filter));
    return;
  }
  if (request.method === 'POST' && url.pathname === '/api/projects') {
    const body = await readJson(request);
    const name = typeof body?.name === 'string' ? body.name.trim() : '';
    if (!name) {
      sendJson(response, 400, { error: 'Project name is required' });
      return;
    }
    const result = createProject.run(name);
    sendJson(response, 201, findProject.get(result.lastInsertRowid));
    return;
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  const archiveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/(archive|restore)$/);
  if (request.method === 'POST' && archiveMatch) {
    const projectId = Number(archiveMatch[1]);
    const project = findProject.get(projectId);
    if (!project) {
      sendJson(response, 404, { error: 'Project not found' });
      return;
    }
    updateProjectArchived.run(archiveMatch[2] === 'archive' ? 1 : 0, projectId);
    sendJson(response, 200, findProject.get(projectId));
    return;
  }
  if (request.method === 'PATCH' && projectMatch) {
    const projectId = Number(projectMatch[1]);
    const project = findProject.get(projectId);
    if (!project) {
      sendJson(response, 404, { error: 'Project not found' });
      return;
    }
    if (project.archived) {
      sendJson(response, 409, { error: 'Archived projects cannot be changed' });
      return;
    }
    const body = await readJson(request);
    const name = typeof body?.name === 'string' ? body.name.trim() : '';
    if (!name) {
      sendJson(response, 400, { error: 'Project name is required' });
      return;
    }
    renameProject.run(name, projectId);
    sendJson(response, 200, findProject.get(projectId));
    return;
  }
  if (request.method === 'GET' && projectMatch) {
    const project = findProject.get(Number(projectMatch[1]));
    sendJson(response, project ? 200 : 404, project || { error: 'Project not found' });
    return;
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch) {
    const projectId = Number(tasksMatch[1]);
    if (!findProject.get(projectId)) {
      sendJson(response, 404, { error: 'Project not found' });
      return;
    }
    if (request.method === 'GET') {
      sendJson(response, 200, listTasks.all(projectId));
      return;
    }
    if (request.method === 'POST') {
      if (findProject.get(projectId).archived) {
        sendJson(response, 409, { error: 'Archived projects cannot be changed' });
        return;
      }
      const body = await readJson(request);
      const title = typeof body?.title === 'string' ? body.title.trim() : '';
      if (!title) {
        sendJson(response, 400, { error: 'Task title is required' });
        return;
      }
      const result = createTask.run(projectId, title);
      sendJson(response, 201, findTask.get(result.lastInsertRowid, projectId));
      return;
    }
  }
  const taskMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
  if (request.method === 'PATCH' && taskMatch) {
    const projectId = Number(taskMatch[1]);
    const taskId = Number(taskMatch[2]);
    const body = await readJson(request);
    const project = findProject.get(projectId);
    if (!project) {
      sendJson(response, 404, { error: 'Project not found' });
      return;
    }
    if (project.archived) {
      sendJson(response, 409, { error: 'Archived projects cannot be changed' });
      return;
    }
    if (typeof body?.completed !== 'boolean') {
      sendJson(response, 400, { error: 'Completion must be a boolean' });
      return;
    }
    updateTaskCompletion.run(body.completed ? 1 : 0, taskId, projectId);
    const task = findTask.get(taskId, projectId);
    sendJson(response, task ? 200 : 404, task || { error: 'Task not found' });
    return;
  }
  if (request.method === 'GET' && (url.pathname === '/' || /^\/projects\/\d+$/.test(url.pathname))) {
    response.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    response.end(html);
    return;
  }
  sendJson(response, 404, { error: 'Not found' });
});

const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0');

function close() {
  server.close(() => {
    database.close();
    process.exit(0);
  });
}

process.on('SIGINT', close);
process.on('SIGTERM', close);
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workboard</title>
  <style>
    :root { color-scheme: light; font-family: system-ui, sans-serif; color: #182230; background: #f5f7fa; }
    body { margin: 0; }
    main { max-width: 720px; margin: 64px auto; padding: 0 24px; }
    h1 { margin: 0 0 28px; font-size: 2rem; }
    form, .project-row, .task-row { display: flex; align-items: center; gap: 12px; }
    form { margin-bottom: 24px; }
    label { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0, 0, 0, 0); }
    input { flex: 1; min-width: 0; padding: 11px 12px; border: 1px solid #b8c2ce; border-radius: 6px; font: inherit; }
    button { padding: 10px 14px; border: 0; border-radius: 6px; background: #2257a5; color: white; font: inherit; font-weight: 600; cursor: pointer; }
    button:hover { background: #174585; }
    button:focus-visible, input:focus-visible { outline: 3px solid #8bb8ff; outline-offset: 2px; }
    [role="alert"] { color: #a12622; margin: 0 0 16px; }
    .project-row { justify-content: space-between; padding: 16px; margin: 10px 0; background: white; border: 1px solid #dce2e9; border-radius: 8px; }
    .project-name { font-weight: 600; overflow-wrap: anywhere; }
    .task-row { justify-content: flex-start; padding: 14px 16px; margin: 10px 0; background: white; border: 1px solid #dce2e9; border-radius: 8px; }
    .task-row input { flex: initial; width: 18px; height: 18px; }
    .task-row label { position: static; width: auto; height: auto; overflow: visible; clip: auto; }
    #task-filter { margin-bottom: 14px; padding: 9px 12px; border: 1px solid #b8c2ce; border-radius: 6px; font: inherit; }
    #project-filter { margin-bottom: 14px; padding: 9px 12px; border: 1px solid #b8c2ce; border-radius: 6px; font: inherit; }
  </style>
</head>
<body>
  <main id="app"></main>
  <script type="module">
    const app = document.querySelector('#app');
    const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);

    async function getProject(id) {
      const response = await fetch(`/api/projects/${encodeURIComponent(id)}`);
      return response.ok ? response.json() : null;
    }

    async function renderList() {
      app.innerHTML = `
        <h1>Workboard</h1>
        <form id="create-project">
          <label for="project-name">Project name</label>
          <input id="project-name" name="name" type="text" aria-label="Project name">
          <button type="submit">Create project</button>
        </form>
        <p id="message" role="alert" hidden></p>
        <label for="project-filter">Project filter</label>
        <select id="project-filter"><option>Active</option><option>Archived</option></select>
        <section id="projects" aria-label="Projects"></section>`;
      const form = app.querySelector('#create-project');
      const input = app.querySelector('#project-name');
      const message = app.querySelector('#message');
      const list = app.querySelector('#projects');
      const filter = app.querySelector('#project-filter');

      async function refresh() {
        const response = await fetch(`/api/projects?filter=${filter.value}`);
        const projects = await response.json();
        list.innerHTML = projects.map((project) => `
          <div class="project-row" data-testid="project-row">
            <span class="project-name">${escapeHtml(project.name)}</span>
            <span data-testid="project-summary">${project.completedCount}/${project.totalCount} completed</span>
            <button type="button" data-project-id="${project.id}">Open project</button>
            <button type="button" data-archive-id="${project.id}">${filter.value === 'Active' ? 'Archive project' : 'Restore project'}</button>
          </div>`).join('');
        list.querySelectorAll('button[data-project-id]').forEach((button) => {
          button.addEventListener('click', () => { window.location.href = `/projects/${button.dataset.projectId}`; });
        });
        list.querySelectorAll('button[data-archive-id]').forEach((button) => {
          button.addEventListener('click', async () => {
            const action = filter.value === 'Active' ? 'archive' : 'restore';
            await fetch(`/api/projects/${button.dataset.archiveId}/${action}`, { method: 'POST' });
            await refresh();
          });
        });
      }

      filter.addEventListener('change', refresh);
      form.addEventListener('submit', async (event) => {
        event.preventDefault();
        message.hidden = true;
        const response = await fetch('/api/projects', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ name: input.value.trim() }),
        });
        if (!response.ok) {
          message.textContent = 'Project name is required';
          message.hidden = false;
          return;
        }
        input.value = '';
        await refresh();
      });
      await refresh();
    }

    async function renderProject(id) {
      const project = await getProject(id);
      if (!project) {
        app.innerHTML = '<h1>Project not found</h1><button type="button" id="back">Projects</button>';
      } else {
        app.innerHTML = `
          <h1>${escapeHtml(project.name)}</h1>
          <button type="button" id="back">Projects</button>
          ${project.archived ? '<p>Archived project</p>' : ''}
          <form id="rename-project">
            <label for="new-project-name">New project name</label>
            <input id="new-project-name" name="name" type="text" aria-label="New project name" ${project.archived ? 'disabled' : ''}>
            <button type="submit" ${project.archived ? 'disabled' : ''}>Rename project</button>
          </form>
          <form id="create-task">
            <label for="task-title">Task title</label>
            <input id="task-title" name="title" type="text" aria-label="Task title" ${project.archived ? 'disabled' : ''}>
            <button type="submit" ${project.archived ? 'disabled' : ''}>Create task</button>
          </form>
          <p id="message" role="alert" hidden></p>
          <label for="task-filter">Task filter</label>
          <select id="task-filter">
            <option>All</option><option>Open</option><option>Completed</option>
          </select>
          <section id="tasks" aria-label="Tasks"></section>`;
        const form = app.querySelector('#create-task');
        const renameForm = app.querySelector('#rename-project');
        const renameInput = app.querySelector('#new-project-name');
        const input = app.querySelector('#task-title');
        const message = app.querySelector('#message');
        const filter = app.querySelector('#task-filter');
        const list = app.querySelector('#tasks');

        async function refresh() {
          const response = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`);
          const tasks = await response.json();
          const visible = tasks.filter((task) => filter.value === 'All'
            || (filter.value === 'Open' && !task.completed)
            || (filter.value === 'Completed' && task.completed));
          list.innerHTML = visible.map((task) => `
            <div class="task-row" data-testid="task-row">
              <input type="checkbox" id="task-${task.id}" data-task-id="${task.id}" ${task.completed ? 'checked' : ''} ${project.archived ? 'disabled' : ''} aria-label="Complete ${escapeHtml(task.title)}">
              <label for="task-${task.id}">${escapeHtml(task.title)}</label>
            </div>`).join('');
          list.querySelectorAll('input[data-task-id]').forEach((checkbox) => {
            checkbox.addEventListener('change', async () => {
              await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${checkbox.dataset.taskId}`, {
                method: 'PATCH',
                headers: { 'content-type': 'application/json' },
                body: JSON.stringify({ completed: checkbox.checked }),
              });
              await refresh();
            });
          });
        }

        filter.addEventListener('change', refresh);
        renameForm.addEventListener('submit', async (event) => {
          event.preventDefault();
          message.hidden = true;
          const response = await fetch(`/api/projects/${encodeURIComponent(id)}`, {
            method: 'PATCH',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ name: renameInput.value.trim() }),
          });
          if (!response.ok) {
            message.textContent = 'Project name is required';
            message.hidden = false;
            return;
          }
          const updatedProject = await response.json();
          app.querySelector('h1').textContent = updatedProject.name;
          renameInput.value = '';
        });
        form.addEventListener('submit', async (event) => {
          event.preventDefault();
          message.hidden = true;
          const response = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`, {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ title: input.value.trim() }),
          });
          if (!response.ok) {
            message.textContent = 'Task title is required';
            message.hidden = false;
            return;
          }
          input.value = '';
          await refresh();
        });
        await refresh();
      }
      app.querySelector('#back').addEventListener('click', () => { window.location.href = '/'; });
    }

    const match = window.location.pathname.match(/^\/projects\/(\d+)$/);
    if (match) await renderProject(match[1]);
    else await renderList();
  </script>
</body>
</html>

